```python
from math import gcd
from functools import reduce

# Prime factorization
def prime_factors(n):
    i = 2
    factors = {}
    while i * i <= n:
        while (n % i) == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n //= i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

# LCM of two numbers
def lcm(a, b):
    return a * b // gcd(a, b)

# LCM of a list of numbers
def lcm_list(numbers):
    return reduce(lcm, numbers)

# Number of days for each planet to rotate around the sun
days = [360, 450, 540]

# Find the LCM of the three numbers
lcm_days = lcm_list(days)

# The minimum positive number of days before the planets are all in the exact same locations again
print(lcm_days)
